local integers = require "wa.integers"
local items = require "wa.items"
local variables = require "wa.variables"

local R = require "core.lib.rathena"
local CARGO_FREE_TICKET = items.id "Cargo_Free_Ticket"
local RESRVPTS = variables.character_integer "resrvpts"

return function(player, conversation, npc, ...)
  local type_, fee, i = 0, 0, 0
  local args = table.pack(...)
  type_ = (R.arg(args, 0) or 0)
  fee = (R.arg(args, 1) or 0)
  if (type_ == 1) then
    if (R.guild_storage(conversation, player) ~= 0) then
      conversation:say("[Kafra Employee]", "I'm sorry but another guild member is using the guild storage", "right now.  Please wait until that person is finished.")
      conversation:hide_image()
      R.stop()
    end
    conversation:hide_image()
    R.stop()
  end
  if (not R.truthy(require("core.functions.F_CanOpenStorage")(player, conversation, npc))) then
    conversation:say("[Kafra Employee]")
    if (R.arg(args, 2) == 1) then
      conversation:say("^666666S-s-ssoooorry,", "y-you're a-a-aaaa", "Nooviiice... N-neeeds", "B-basic sssskill l-level 6...^000000")
      do return end
    end
    conversation:say("I'm sorry, but you", "need the Novice's", "Basic Skill Level 6 to", "use the Storage Service.")
    do return end
  end
  if (type_ ~= 2) then
    if (player:count_item(CARGO_FREE_TICKET) ~= 0) then
      player:take_item(CARGO_FREE_TICKET, 1)
    else
      if (player.zeny < fee) then
        conversation:say("[Kafra Employee]")
        if (R.arg(args, 2) == 1) then
          player:heal_percent { hp = -50, sp = -50 }
          conversation:say("^666666Zeeeeeny...", "M-more z-zeny...!", "N-neeed 150... zeny...", "Ergh! T-taking bl-blood~!^000000")
          do return end
        end
        conversation:say("I'm sorry, but you don't", "have enough zeny to use", "the Storage Service. Our", "Storage access fee is " .. fee .. " zeny.")
        do return end
      end
      player:pay_zeny(fee)
      RESRVPTS:add(player, integers.divide_truncated(fee, 5))
    end
  end
  if (type_ ~= 2) then
    if (R.arg(args, 2) == 1) then
      player:heal_percent { sp = -10 }
      conversation:say("[Kafra Employee]")
      i = 0
      while (i < 5) do
        conversation:say("^666666Thank you.. for... using...^000000")
        i = (i + 1)
      end
    else
      conversation:say("[Kafra Employee]", "Here, let me open", "your Storage for you.", "Thank you for using", "the Kafra Service.")
    end
  end
  require("core.functions.F_CheckKafCode")(player, conversation, npc)
  conversation:close()
  player:open_storage()
  conversation:hide_image()
  R.stop()
end
